mapper.delete:
DELETE FROM rag_document
 WHERE revision_id = #{revisionId}
   AND source_path = #{sourcePath}
   AND source_type = 'CODE'

mapper.insert:
INSERT INTO rag_chunk
    (doc_seq, revision_id, chunk_no, chunk_type, content, content_hash, char_count, metadata_json, file_id, line_start, line_end)
SELECT d.doc_seq, #{revisionId}, #{chunkNo}, #{chunkType}, #{content}, #{contentHash}, #{charCount}
     , CAST(#{metadataJson} AS jsonb), #{fileId}, #{lineStart, jdbcType=INTEGER}, #{lineEnd, jdbcType=INTEGER}
  FROM rag_document d
 WHERE d.document_id = #{documentId}
   AND d.revision_id = #{revisionId}

mapper.update:
UPDATE rag_embedding
   SET attempts = attempts + 1
     , last_error = #{lastError}
     , status = CASE WHEN attempts + 1 >= 3 THEN 'FAILED' ELSE 'PENDING' END
 WHERE content_hash = #{contentHash}
   AND model = #{model}

mapper.delete:
DELETE FROM rag_embedding
 WHERE content_hash = #{contentHash}
   AND model = #{model}

mapper.select:
SELECT COALESCE(e.status, 'NONE') AS "status", COUNT(*) AS "chunks"
  FROM rag_chunk c
  LEFT JOIN rag_embedding e ON e.content_hash = c.content_hash AND e.model = #{model}
 WHERE c.revision_id = #{revisionId}
 GROUP BY e.status
 ORDER BY 1

